begin;
update public.aios_audit_events set actor_type=coalesce(nullif(actor_type,''),'system') where actor_type is null or actor_type='';
do $$ declare r record; prev text; h text; begin for r in select * from public.aios_audit_events order by organization_id,created_at,id loop if r.event_hash is null then prev=coalesce((select e.event_hash from public.aios_audit_events e where e.organization_id=r.organization_id and e.event_hash is not null order by e.created_at desc,e.id desc limit 1),'GENESIS:'||r.organization_id::text); h=encode(digest(jsonb_build_object('id',r.id,'organization_id',r.organization_id,'actor_user_id',r.actor_user_id,'actor_type',r.actor_type,'agent_id',r.agent_id,'mission_id',r.mission_id,'task_id',r.task_id,'invocation_id',r.invocation_id,'event_type',r.event_type,'previous_state',r.previous_state,'new_state',r.new_state,'tool_name',r.tool_name,'risk_level',r.risk_level,'arguments_hash',r.arguments_hash,'result_hash',r.result_hash,'approval_id',r.approval_id,'created_at',r.created_at,'metadata',r.metadata,'previous_event_hash',prev)::text||prev,'sha256'),'hex'); update public.aios_audit_events set previous_event_hash=prev,event_hash=h where id=r.id; end if; end loop; end $$;
create trigger trg_aios_audit_hash before insert on public.aios_audit_events for each row execute function private.aios_audit_append();
create trigger trg_aios_audit_immutable_update before update on public.aios_audit_events for each row execute function private.aios_audit_immutable();
create trigger trg_aios_audit_immutable_delete before delete on public.aios_audit_events for each row execute function private.aios_audit_immutable();
commit;
